import * as React from "react";
import * as RechartsPrimitive from "recharts";

import { cn } from "@/lib/utils.js";

// Generated by `pnpm dlx shadcn@latest add chart`, then adapted — the
// generated file needs three things before it belongs in this repo:
//
//   1. JSDoc on every component. The CLI emits none, and `pnpm typecheck`
//      runs with `checkJs` + `strict`, so an unannotated file fails.
//   2. `@/lib/utils` → `@/lib/utils.js`. Vite resolves the extensionless
//      form, TypeScript's "Bundler" resolution does not.
//   3. Its light/dark split removed. The generated ChartStyle emits one
//      block per theme keyed on a `.dark` CLASS selector, and this app has
//      no such class — it themes on `[data-theme="dark"]` plus a
//      `prefers-color-scheme` media query (styles/tokens.css). Every
//      `.dark`-prefixed rule would be dead, silently, in the same way the
//      generated `data-active:` utilities in ui/tabs.jsx were.
//
// The split is not merely fixed but removed, because there is nothing left
// for it to do: unlike the ECharts canvas this replaces, Recharts draws
// SVG, so a series colour can be `var(--chart-line-1)` and the browser
// re-resolves it on a theme change with no JS, no re-read of the tokens and
// no oklch()-to-sRGB conversion. Pass CSS variables as colours; do not read
// computed styles.

/**
 * Per-series metadata: the label a tooltip and legend show, and the colour
 * the series draws in. Each key becomes a `--color-<key>` custom property on
 * the chart's own element, which is how a Recharts `fill`/`stroke` reaches
 * it (`fill="var(--color-balance)"`).
 *
 * @typedef {Record<string, {
 *   label?: import("react").ReactNode,
 *   icon?: import("react").ComponentType,
 *   color?: string,
 * }>} ChartConfig
 */

/** @typedef {{ config: ChartConfig }} ChartContextValue */

const ChartContext = React.createContext(/** @type {ChartContextValue | null} */ (null));

function useChart() {
  const context = React.useContext(ChartContext);

  if (!context) {
    throw new Error("useChart must be used within a <ChartContainer />");
  }

  return context;
}

const INITIAL_DIMENSION = { width: 320, height: 200 };

/**
 * @param {Omit<import("react").ComponentProps<"div">, "children"> & {
 *   config: ChartConfig,
 *   children: import("react").ComponentProps<typeof RechartsPrimitive.ResponsiveContainer>["children"],
 *   initialDimension?: { width: number, height: number },
 * }} props
 */
function ChartContainer({
  id,
  className,
  children,
  config,
  initialDimension = INITIAL_DIMENSION,
  ...props
}) {
  const uniqueId = React.useId();
  const chartId = `chart-${id ?? uniqueId.replace(/:/g, "")}`;
  const value = React.useMemo(() => ({ config }), [config]);

  return (
    <ChartContext.Provider value={value}>
      <div
        data-slot="chart"
        data-chart={chartId}
        // `size-full` rather than the generated `aspect-video`: <Chart> owns
        // the height, and an aspect ratio fighting an explicit height is how
        // a chart ends up 0px tall.
        className={cn(
          "flex size-full justify-center text-xs [&_.recharts-cartesian-axis-tick_text]:fill-muted-foreground [&_.recharts-cartesian-grid_line[stroke='#ccc']]:stroke-border [&_.recharts-curve.recharts-tooltip-cursor]:stroke-border [&_.recharts-dot[stroke='#fff']]:stroke-transparent [&_.recharts-layer]:outline-hidden [&_.recharts-polar-grid_[stroke='#ccc']]:stroke-border [&_.recharts-radial-bar-background-sector]:fill-muted [&_.recharts-rectangle.recharts-tooltip-cursor]:fill-muted [&_.recharts-reference-line_[stroke='#ccc']]:stroke-border [&_.recharts-sector]:outline-hidden [&_.recharts-sector[stroke='#fff']]:stroke-transparent [&_.recharts-surface]:outline-hidden",
          className,
        )}
        {...props}
      >
        <ChartStyle id={chartId} config={config} />
        <RechartsPrimitive.ResponsiveContainer initialDimension={initialDimension}>
          {children}
        </RechartsPrimitive.ResponsiveContainer>
      </div>
    </ChartContext.Provider>
  );
}

/**
 * Publishes each configured series colour as `--color-<key>` scoped to this
 * one chart. One block, not one per theme — see the note at the top.
 *
 * @param {{ id: string, config: ChartConfig }} props
 */
function ChartStyle({ id, config }) {
  const colorConfig = Object.entries(config).filter(([, item]) => item.color);

  if (!colorConfig.length) {
    return null;
  }

  return (
    <style
      dangerouslySetInnerHTML={{
        __html: `[data-chart=${id}] {\n${colorConfig
          .map(([key, item]) => `  --color-${key}: ${item.color};`)
          .join("\n")}\n}`,
      }}
    />
  );
}

const ChartTooltip = RechartsPrimitive.Tooltip;

/**
 * One entry in what Recharts hands a tooltip. Typed structurally rather than
 * imported: Recharts' own payload type is generic over the data row, and
 * every call site here passes a differently-shaped row.
 *
 * @typedef {{
 *   type?: string,
 *   name?: string | number,
 *   dataKey?: string | number,
 *   value?: unknown,
 *   color?: string,
 *   payload?: Record<string, unknown>,
 * }} TooltipItem
 */

/**
 * @param {{
 *   active?: boolean,
 *   payload?: TooltipItem[],
 *   className?: string,
 *   indicator?: 'line' | 'dot' | 'dashed',
 *   hideLabel?: boolean,
 *   hideIndicator?: boolean,
 *   label?: unknown,
 *   labelFormatter?: (label: import("react").ReactNode, payload: TooltipItem[]) => import("react").ReactNode,
 *   labelClassName?: string,
 *   formatter?: (
 *     value: unknown,
 *     name: string | number,
 *     item: TooltipItem,
 *     index: number,
 *     payload: unknown,
 *   ) => import("react").ReactNode,
 *   valueFormatter?: (value: unknown, item: TooltipItem) => import("react").ReactNode,
 *   color?: string,
 *   nameKey?: string,
 *   labelKey?: string,
 * }} props
 */
function ChartTooltipContent({
  active,
  payload,
  className,
  indicator = "dot",
  hideLabel = false,
  hideIndicator = false,
  label,
  labelFormatter,
  labelClassName,
  formatter,
  valueFormatter,
  color,
  nameKey,
  labelKey,
}) {
  const { config } = useChart();

  const tooltipLabel = React.useMemo(() => {
    if (hideLabel || !payload?.length) {
      return null;
    }

    const [item] = payload;
    const key = `${labelKey ?? item?.dataKey ?? item?.name ?? "value"}`;
    const itemConfig = getPayloadConfigFromPayload(config, item, key);
    const value =
      !labelKey && typeof label === "string" ? (config[label]?.label ?? label) : itemConfig?.label;

    if (labelFormatter) {
      return <div className={cn("font-medium", labelClassName)}>{labelFormatter(value, payload)}</div>;
    }

    if (!value) {
      return null;
    }

    return <div className={cn("font-medium", labelClassName)}>{value}</div>;
  }, [label, labelFormatter, payload, hideLabel, labelClassName, config, labelKey]);

  if (!active || !payload?.length) {
    return null;
  }

  const nestLabel = payload.length === 1 && indicator !== "dot";

  return (
    <div
      // `bg-popover` and the raised shadow, not the generated
      // `bg-background`: this is a floating surface over the page, and every
      // other one in the app (dropdown, select, popover) reads that token.
      className={cn(
        "grid min-w-32 items-start gap-1.5 rounded-(--radius-control) border border-border bg-popover px-2.5 py-1.5 text-xs text-popover-foreground shadow-[var(--shadow-raised)]",
        className,
      )}
    >
      {!nestLabel ? tooltipLabel : null}
      <div className="grid gap-1.5">
        {payload
          // `value == null` as well as `type === "none"`: a sparse series
          // (bill markers on the days a bill falls, and nothing on the days
          // it doesn't) otherwise contributes a labelled row with no figure
          // beside it to every other day's tooltip.
          .filter((item) => item.type !== "none" && item.value != null)
          .map((item, index) => {
            const key = `${nameKey ?? item.name ?? item.dataKey ?? "value"}`;
            const itemConfig = getPayloadConfigFromPayload(config, item, key);
            const indicatorColor = color ?? item.payload?.fill ?? item.color;

            return (
              <div
                key={index}
                className={cn(
                  "flex w-full flex-wrap items-stretch gap-2 [&>svg]:h-2.5 [&>svg]:w-2.5 [&>svg]:text-muted-foreground",
                  indicator === "dot" && "items-center",
                )}
              >
                {formatter && item?.value !== undefined && item.name !== undefined ? (
                  formatter(item.value, item.name, item, index, item.payload)
                ) : (
                  <>
                    {itemConfig?.icon ? (
                      <itemConfig.icon />
                    ) : (
                      !hideIndicator && (
                        <div
                          className={cn("shrink-0 rounded-[2px] border-(--color-border) bg-(--color-bg)", {
                            "h-2.5 w-2.5": indicator === "dot",
                            "w-1": indicator === "line",
                            "w-0 border-[1.5px] border-dashed bg-transparent": indicator === "dashed",
                            "my-0.5": nestLabel && indicator === "dashed",
                          })}
                          style={/** @type {import("react").CSSProperties} */ ({
                            "--color-bg": indicatorColor,
                            "--color-border": indicatorColor,
                          })}
                        />
                      )
                    )}
                    <div
                      className={cn(
                        "flex flex-1 justify-between leading-none",
                        nestLabel ? "items-end" : "items-center",
                      )}
                    >
                      <div className="grid gap-1.5">
                        {nestLabel ? tooltipLabel : null}
                        <span className="text-muted-foreground">{itemConfig?.label ?? item.name}</span>
                      </div>
                      {item.value != null && (
                        <span className="font-medium text-foreground tabular-nums">
                          {/* `valueFormatter` is an addition to the generated
                              component: `formatter` above replaces the entire
                              row, and every chart here wants the default row
                              with the value spelled as money. */}
                          {valueFormatter
                            ? valueFormatter(item.value, item)
                            : typeof item.value === "number"
                              ? item.value.toLocaleString()
                              : String(item.value)}
                        </span>
                      )}
                    </div>
                  </>
                )}
              </div>
            );
          })}
      </div>
    </div>
  );
}

const ChartLegend = RechartsPrimitive.Legend;

/**
 * @param {{
 *   className?: string,
 *   hideIcon?: boolean,
 *   payload?: TooltipItem[],
 *   verticalAlign?: 'top' | 'middle' | 'bottom',
 *   nameKey?: string,
 * }} props
 */
function ChartLegendContent({ className, hideIcon = false, payload, verticalAlign = "bottom", nameKey }) {
  const { config } = useChart();

  if (!payload?.length) {
    return null;
  }

  return (
    <div
      className={cn(
        "flex flex-wrap items-center justify-center gap-x-4 gap-y-1",
        verticalAlign === "top" ? "pb-3" : "pt-3",
        className,
      )}
    >
      {payload
        .filter((item) => item.type !== "none")
        .map((item, index) => {
          const key = `${nameKey ?? item.dataKey ?? "value"}`;
          const itemConfig = getPayloadConfigFromPayload(config, item, key);

          return (
            <div
              key={index}
              className="flex items-center gap-1.5 text-muted-foreground [&>svg]:h-3 [&>svg]:w-3 [&>svg]:text-muted-foreground"
            >
              {itemConfig?.icon && !hideIcon ? (
                <itemConfig.icon />
              ) : (
                <div className="h-2 w-2 shrink-0 rounded-[2px]" style={{ backgroundColor: item.color }} />
              )}
              {itemConfig?.label ?? key}
            </div>
          );
        })}
    </div>
  );
}

/**
 * @param {ChartConfig} config
 * @param {unknown} payload
 * @param {string} key
 */
function getPayloadConfigFromPayload(config, payload, key) {
  if (typeof payload !== "object" || payload === null) {
    return undefined;
  }

  const record = /** @type {Record<string, unknown>} */ (payload);
  const inner = record.payload;
  const payloadPayload =
    typeof inner === "object" && inner !== null ? /** @type {Record<string, unknown>} */ (inner) : undefined;

  let configLabelKey = key;

  if (typeof record[key] === "string") {
    configLabelKey = /** @type {string} */ (record[key]);
  } else if (payloadPayload && typeof payloadPayload[key] === "string") {
    configLabelKey = /** @type {string} */ (payloadPayload[key]);
  }

  return config[configLabelKey] ?? config[key];
}

export { ChartContainer, ChartTooltip, ChartTooltipContent, ChartLegend, ChartLegendContent, ChartStyle };
